'use strict';
fetch('data/course.json',{cache:'no-cache'}).then(response=>{if(!response.ok)throw Error('Не удалось загрузить курс');return response.json();}).then(bundle=>{
 window.textbookApp=GeometryTextbook.createApp(document.getElementById('textbook-app'),bundle);
}).catch(()=>{document.getElementById('textbook-app').textContent='Материалы сейчас не удалось открыть. Попробуй обновить страницу.';});
</script></body></html>

changes.after:
'use strict';
const catalogue=document.getElementById('textbook-catalog'),loadStatus=document.getElementById('textbook-load-status'),retry=document.getElementById('textbook-retry'),numberField=document.getElementById('textbook-number'),findNumber=document.getElementById('textbook-number-find'),numberMessage=document.getElementById('textbook-number-message');
let loading=false,initializing=false;
async function loadCatalogue(){
 if(loading)return;loading=true;retry.hidden=true;findNumber.disabled=true;loadStatus.textContent='Каталог загружается… Темы уже доступны.';
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),30000);
 try{
  const response=await fetch('data/course.json',{cache:'no-cache',signal:controller.signal});if(!response.ok)throw Error('Курс недоступен');const bundle=await response.json();
  initializing=true;window.textbookApp=GeometryTextbook.createApp(catalogue,bundle);initializing=false;
  findNumber.disabled=false;loadStatus.textContent='Каталог готов.';
 }catch{
  catalogue.replaceChildren();loadStatus.textContent='Каталог не загрузился. Откройте тему или попробуйте ещё раз.';retry.textContent=initializing?'Обновить страницу':'Повторить загрузку';retry.hidden=false;
 }finally{clearTimeout(timeout);loading=false;}
}
document.getElementById('textbook-number-form').addEventListener('submit',event=>{
 event.preventDefault();const value=numberField.value.trim().replace(/^№\s*/, '');
 if(!/^\d+$/.test(value)||Number(value)<1||Number(value)>1431){numberMessage.textContent='Введите номер задачи от 1 до 1431, например 61.';numberField.focus();return;}
 if(!window.textbookApp){numberMessage.textContent='Дождитесь загрузки каталога или откройте тему рядом.';return;}
 numberMessage.textContent='';window.textbookApp.home();const search=document.getElementById('catalog-search');
 document.getElementById('catalog-kind').value='exercise';document.getElementById('catalog-collection').value='main';document.getElementById('catalog-chapter').value='';search.value=String(Number(value));search.dispatchEvent(new Event('input',{bubbles:true}));search.focus();search.scrollIntoView({block:'start'});
});
// A failed application initialization can leave runtime event listeners behind.
// Recreate the document in that case; a failed download only needs a new fetch.
retry.addEventListener('click',()=>{if(initializing)location.reload();else loadCatalogue();});
catalogue.addEventListener('click',event=>{
 if(event.ctrlKey||event.metaKey||event.shiftKey||event.altKey||event.button!==0)return;
 if(event.target.closest('a[data-lesson]')||event.target.closest('.textbook-lesson-header button'))window.scrollTo(0,0);
});
loadCatalogue();
</script></body></html>
